import {shell,mount} from './components.js';
import {readIntegrations,saveIntegrations} from './integration-store.js';
const $=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let active='external',editing=null;
function render(){const store=readIntegrations();mount(shell({active:'api',content:`<h1 id="api-title">API設定</h1><nav class="api-tabs" aria-label="API設定">${[['url','API URL'],['key','APIキー管理'],['notify','通知先URL'],['external','外部データ連携']].map(([id,n])=>`<button data-tab="${id}" class="${active===id?'active':''}">${n}</button>`).join('')}</nav>${active==='external'?`<div class="toolbar"><span></span><button id="add-connection" class="button primary">＋ 接続を追加</button></div><div class="connection-table"><table><thead><tr><th>No.</th><th>接続名</th><th>接続先URL</th><th>作成日時</th><th>ステータス</th><th>作成者</th><th>操作・処理</th></tr></thead><tbody>${store.connections.map((c,i)=>`<tr><td>${i+1}</td><td>${esc(c.name)}</td><td>${esc(c.url||'—')}</td><td>${esc(c.created)}</td><td>未接続</td><td>${esc(c.creator)}</td><td><div class="row"><button class="button link" data-edit="${esc(c.id)}">編集</button><button class="button link danger" data-delete="${esc(c.id)}">削除</button></div></td></tr>`).join('')||'<tr><td colspan="7">接続がありません。</td></tr>'}</tbody></table></div>`:`<section class="panel"><a class="button" href="https://neosai-idp.vercel.app/business-rules/api-management" target="_blank" rel="noopener">現行画面を開く</a></section>`}<div id="feedback" class="api-toast" role="status" hidden></div><dialog id="connection-dialog"><div class="dialog-head"><h2>外部接続設定</h2><button data-close class="button link">閉じる</button></div><div class="dialog-body"><div class="field"><label for="connection-name">接続名</label><input id="connection-name" type="text" required></div><div class="field"><label for="connection-url">接続先URL</label><input id="connection-url" type="url" required placeholder="https://api.example.com"></div></div><div class="dialog-foot"><button data-close class="button">キャンセル</button><button id="save-connection" class="button primary">保存</button></div></dialog><dialog id="delete-dialog"><div class="dialog-head"><h2>接続を削除</h2></div><div class="dialog-body"><p id="delete-label"></p></div><div class="dialog-foot"><button data-close class="button">キャンセル</button><button id="confirm-delete" class="button primary">OK</button></div></dialog>`}));
const nav=document.querySelector('.sidebar');nav.querySelectorAll('a').forEach(e=>e.remove());nav.insertAdjacentHTML('beforeend','<a class="active sub" href="./api-settings.html">API設定</a>');const m=Array.from(nav.querySelectorAll('.item')).find(e=>e.textContent==='マスタデータ設定');if(m)m.outerHTML='<a class="sub" href="./master-data.html" data-nav="master-data">マスタデータ設定</a>';
document.querySelectorAll('[data-tab]').forEach(e=>e.onclick=()=>{active=e.dataset.tab;render()});document.querySelectorAll('[data-close]').forEach(e=>e.onclick=()=>e.closest('dialog').close());
if($('add-connection'))$('add-connection').onclick=()=>openConnection(null);
document.querySelectorAll('[data-edit]').forEach(e=>e.onclick=()=>openConnection(e.dataset.edit));
document.querySelectorAll('[data-delete]').forEach(e=>e.onclick=()=>{const st=readIntegrations(),c=st.connections.find(c=>c.id===e.dataset.delete);if(Object.values(st.jobs).some(j=>j.connection===c.id)){feedback('この接続はマスタ同期設定で使用されています。先に接続を変更してください。');return}$('delete-label').textContent=c.name+' を削除しますか？';$('confirm-delete').onclick=()=>{const st=readIntegrations();if(Object.values(st.jobs).some(j=>j.connection===c.id)){feedback('この接続は使用されています。');$('delete-dialog').close();return}st.connections=st.connections.filter(x=>x.id!==c.id);saveIntegrations(st);render()};$('delete-dialog').showModal()});
$('save-connection').onclick=()=>{if(!$('connection-name').value.trim()){$('connection-name').reportValidity();return}if(!$('connection-url').checkValidity()){$('connection-url').reportValidity();return}const st=readIntegrations(),old=st.connections.find(c=>c.id===editing);const c={id:editing||crypto.randomUUID(),name:$('connection-name').value.trim(),url:$('connection-url').value,created:old?.created||new Date().toLocaleString('sv-SE',{timeZone:'Asia/Tokyo'}),creator:old?.creator||'管理者'};if(old)st.connections[st.connections.indexOf(old)]=c;else st.connections.push(c);saveIntegrations(st);render()};}
function feedback(t){$('feedback').textContent=t;$('feedback').hidden=false;setTimeout(()=>$('feedback').hidden=true,4500)}
function openConnection(id){editing=id;const c=readIntegrations().connections.find(c=>c.id===id);$('connection-name').value=c?.name||'';$('connection-url').value=c?.url||'';document.querySelectorAll('.api-note').forEach(e=>e.remove());$('connection-dialog').showModal()}
render();
